def _phase0_is_pre_deadline(gw):
    try:
        deadline = _phase0_deadlines.get(int(gw))
    except Exception:
        deadline = None
    if deadline is None:
        return pd.NA
    return bool(_snapshot_ts < deadline)


def _phase0_stamp(frame, *, source, gw_col=None, fixture_col=None, fixed_gw=None):
    out = frame.copy().reset_index(drop=True)
    out["model_version"] = model_version
    out["data_snapshot_timestamp"] = data_snapshot_timestamp
    out["forecast_timestamp"] = forecast_timestamp

    if gw_col and gw_col in out.columns:
        out["gameweek"] = pd.to_numeric(out[gw_col], errors="coerce").astype("Int64")
    elif fixed_gw is not None:
        out["gameweek"] = int(fixed_gw)
    else:
        out["gameweek"] = pd.Series([pd.NA] * len(out), dtype="Int64")

    if fixture_col and fixture_col in out.columns:
        out["fixture_id"] = pd.to_numeric(out[fixture_col], errors="coerce").astype("Int64")
    else:
        out["fixture_id"] = pd.Series([pd.NA] * len(out), dtype="Int64")

    out["source_name"] = str(source)
    out["source_timestamp"] = data_snapshot_timestamp
    out["is_pre_deadline_data"] = out["gameweek"].map(_phase0_is_pre_deadline)
    return out


