def to_list(
    value
):

    if isinstance(
        value,
        list
    ):

        return value


    if isinstance(
        value,
        tuple
    ):

        return list(
            value
        )


    if value is None:

        return []


    if isinstance(
        value,
        str
    ):

        text = (
            value.strip()
        )


        if not text:

            return []


        try:

            parsed = (
                ast.literal_eval(
                    text
                )
            )


            if isinstance(
                parsed,
                (
                    list,
                    tuple,
                )
            ):

                return list(
                    parsed
                )


        except Exception:

            pass


        return [
            text
        ]


    try:

        if pd.isna(
            value
        ):

            return []


    except Exception:

        pass


    return [
        value
    ]


def model_fdr_visual_class(value):
    """Presentation colour only; decision math remains the exact Phase-4 FDR values."""
    values = _vx_numeric_fdr_values(value)
    if not values:
        return "fdr-none"
    # DGW colour is presentation-only; Attack and Defence values are never blended together.
    visual_value = float(np.mean(values))
    band = str(vx_phase4_fdr_colour_band(visual_value))
    return {
        "Dark green": "fdr-1",
        "Green": "fdr-2",
        "Grey": "fdr-3",
        "Orange": "fdr-4",
        "Red": "fdr-5",
    }.get(band, "fdr-none")








