def build_fdr_panel(
    rows
):
    rows_html = "".join(
        build_team_row(row)
        for row in rows
    )

    gw_header_html = "".join(
        f"<div>{escape(label)}</div>"
        for label in GW_HEADERS
    )

    return f"""
    <section class="table-panel">
        <div class="column-header">
            <div class="team-header">TEAM</div>
            {gw_header_html}
            <div>AVG A/D</div>
        </div>
        <div class="table-body">
            {rows_html}
        </div>
    </section>
    """


