# ------------------------------------------------------------
# REAL GAMEWEEK COLUMN LABELS
# Example when MODEL_NEXT_GW == 2: GW2, GW3, GW4, GW5, GW6, GW7
# ------------------------------------------------------------
GW_HEADERS = [
    f"GW{MODEL_NEXT_GW + offset}"
    for offset in range(6)
]


# ============================================================
# 16. COLOR SYSTEM
#
# SAME VORTEX DIRECTION AS FDR:
#
# BEST     = MINT
# GOOD     = GREEN
# NEUTRAL  = SLATE
# WEAK     = AMBER
# POOR     = RED
# ============================================================

def xg_class(
    value
):
    value = finite(value, 0)

    # 0–1.00 RED | 1.01–1.20 GOLD | 1.21–1.40 SKY | >=1.41 GREEN
    if value <= 1.00:
        return "tier-5"
    if value <= 1.20:
        return "tier-4"
    if value <= 1.50:
        return "tier-3"
    return "tier-1"


def cs_class(
    value
):
    """Unified with xg_class: same fixed thresholds/tier scheme as Projected Goals."""
    value = finite(value, 0)
    p_cs = float(np.clip(value / 100.0, 0.0, 1.0)) * 100.0

    # 0-20% RED | 20.01-25% GOLD | 25.01-45% SKY | >=35.01% GREEN
    if p_cs <= 30.0:
        return "tier-5"
    if p_cs <= 45.0:
        return "tier-4"
    if p_cs <= 60.0:
        return "tier-3"
    return "tier-1"


# ============================================================
# 17. HTML ROW BUILDER
# ============================================================

def opponent_badges_html(
    opponent_ids
):

    badges = []


    if not isinstance(
        opponent_ids,
        list
    ):

        return ""


    for opponent_id in (
        opponent_ids[:2]
    ):

        try:

            opponent_id = int(
                opponent_id
            )

        except Exception:

            continue


        badge = (
            team_meta
            .get(
                opponent_id,
                {}
            )
            .get(
                "badge",
                ""
            )
        )


        if badge:

            badges.append(

                '<img '
                'class="opponent-badge" '
                'src="'

                +
                badge

                +
                '" alt="">'
            )


    return "".join(
        badges
    )


def build_metric_row(
    item,
    metric
):

    team_name = escape(

        str(
            item["team"]
        ).upper()
    )


    badge = str(
        item.get(
            "badge",
            ""
        )
    )


    if badge:

        team_badge_html = (

            '<img class="team-badge" src="'

            +
            badge

            +
            '" alt="">'
        )


    else:

        team_badge_html = (

            '<div class="team-badge-placeholder">'
            '</div>'
        )


    cards = []


    for index in range(
        1,
        7
    ):

        opponent = escape(

            str(
                item[
                    f"gw{index}_opponent"
                ]
            )
        )


        opponent_ids = (
            item[
                f"gw{index}_opponent_ids"
            ]
        )


        badges_html = (
            opponent_badges_html(
                opponent_ids
            )
        )


        if metric == "xg":

            value = finite(

                item[
                    f"gw{index}_xg"
                ],

                0
            )


            display_value = (
                "—"
                if opponent == "BLANK"
                else
                f"{value:.2f}"
            )


            tier = (
                xg_class(
                    value
                )
            )


        else:

            value = finite(

                item[
                    f"gw{index}_cs"
                ],

                0
            )


            display_value = (
                "—"
                if opponent == "BLANK"
                else
                f"{value:.0f}%"
            )


            tier = (
                "fdr-none"
                if opponent == "BLANK"
                else cs_class(value)
            )


        cards.append(
            f"""

            <div class="metric-card {tier}">

                <div class="fixture-top">

                    <div class="opponent-badges">
                        {badges_html}
                    </div>

                    <div class="fixture-name">
                        {opponent}
                    </div>

                </div>

                <div class="metric-number">
                    {display_value}
                </div>

            </div>

            """
        )


    if metric == "xg":

        average = finite(
            item[
                "avg_xg"
            ],
            0
        )


        average_text = (
            f"{average:.2f}"
        )


        average_tier = (
            xg_class(
                average
            )
        )


    else:

        average = finite(
            item[
                "avg_cs"
            ],
            0
        )


        average_text = (
            f"{average:.0f}%"
        )


        average_tier = (
            cs_class(
                average
            )
        )


    return f"""

    <div class="team-row">

        <div class="team-cell">

            {team_badge_html}

            <div class="team-name">
                {team_name}
            </div>

        </div>

        {''.join(cards)}

        <div class="avg-cell {average_tier}">

            <span>
                {average_text}
            </span>

        </div>

    </div>

    """


# ============================================================
# 18. PANEL BUILDER
# ============================================================

def build_projection_panel(
    records,
    metric
):
    rows = "".join(
        build_metric_row(record, metric)
        for record in records
    )

    gw_header_html = "".join(
        f"<div>{escape(label)}</div>"
        for label in GW_HEADERS
    )

    return f"""
    <section class="table-panel">
        <div class="column-header">
            <div class="team-header">TEAM</div>
            {gw_header_html}
            <div>AVG</div>
        </div>
        <div class="table-body">
            {rows}
        </div>
    </section>
    """


