# ------------------------------------------------------------
# SHARED DETERMINISTIC JS
# ------------------------------------------------------------

JS = r"""
<script id="vx-shared-engine">

const VX=__VX__;

function clamp(x,a=0,b=1){
    return Math.max(a,Math.min(b,x));
}

function ease(x){
    x=clamp(x);
    return 1-Math.pow(1-x,3);
}

function pulse(x){
    return Math.sin(clamp(x)*Math.PI);
}

function normalize(x){
    return String(x||"")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g," ")
      .trim();
}

function bestTextElement(txt){

    const q=normalize(txt);
    let best=null, size=1e9;

    document.querySelectorAll(
      "tr,.team-row,.club,.panel,td,div,span"
    ).forEach(el=>{

        const s=normalize(el.innerText);

        if(
            s &&
            s.includes(q) &&
            s.length<size
        ){
            best=el;
            size=s.length;
        }
    });

    return best;
}

let bindings=[];
let highlights=[];

function initVX(){

    const seen=new Set();

    VX.events.forEach(e=>{

        let els=[];

        try{
            els=[...document.querySelectorAll(e.sel)];
        }catch(_){}

        els.forEach((el,i)=>{

            if(seen.has(el)) return;

            seen.add(el);
            el.classList.add("vx-managed");

            bindings.push({
                el,
                at:e.at+i*e.stagger,
                dur:e.dur,
                fx:e.fx
            });
        });
    });

    VX.highlights.forEach(h=>{

        const el=bestTextElement(h.text);

        if(el){
            el.classList.add("vx-spoken");

            highlights.push({
                el,
                at:h.at,
                dur:1.15
            });
        }
    });

    if(Array.isArray(VX.teasers) && VX.teasers.length){
        const teaser=document.createElement("div");
        teaser.id="vxDeadAirTeaser";
        teaser.innerHTML=
          '<div class="vxFactKicker">VORTEX QUICK READ</div>'+
          '<div class="vxFactText"></div>'+
          '<div class="vxFactRule"></div>';
        document.body.appendChild(teaser);
    }

    window.__ready=true;
    window.__seek(0);
}

/* --------------------------------------------------------
   SEEK
   -------------------------------------------------------- */

window.__seek=function(t){

    t=clamp(Number(t)||0,0,VX.duration);

    /* standard entrances */
    bindings.forEach(b=>{

        const p=ease((t-b.at)/b.d);

        b.el.style.opacity=p;

        if(b.fx==="left")
            b.el.style.transform=
              `translateX(${(1-p)*-55}px)`;

        else if(b.fx==="rise")
            b.el.style.transform=
              `translateY(${(1-p)*42}px)
               scale(${.98+.02*p})`;

        else if(b.fx==="zoom")
            b.el.style.transform=
              `scale(${.88+.12*p})`;

        else if(b.fx==="type"){
            b.el.style.transform=`translateY(${(1-p)*28}px) scale(${.985+.015*p})`;
            const title=b.el.querySelector("[data-vx-type]");
            if(title){
                const full=title.dataset.vxType || "";
                if(t < b.at) title.textContent="";
                else{
                    const tp=clamp((t-b.at)/b.dur);
                    const n=Math.floor(full.length*tp);
                    title.textContent=full.slice(0,n) + (tp<1 ? "▌" : "");
                }
            }
        }

        else
            b.el.style.transform="none";
    });

    /* narrated team pulse */
    highlights.forEach(h=>{

        const p=pulse((t-h.at)/h.d);

        h.el.style.filter=
          p>0
          ? `brightness(${1+.25*p})
             saturate(${1+.20*p})`
          : "";

        h.el.style.boxShadow=
          p>0
          ? `0 0 ${20+35*p}px
             rgba(0,229,220,${.12+.28*p})`
          : "";
    });
        /* pre-agenda fixture grid — plain show/hide window, no typewriter */
    const fxGridEl=document.querySelector("#vxFixtureGrid");
    if(fxGridEl && VX.fixture_grid_window){
        const w=VX.fixture_grid_window;
        const inWindow=t>=w.at && t<w.end;
        fxGridEl.style.opacity=inWindow ? "1" : "0";
    }
        /* row zoom-to-center: only the currently narrated team row */
    if(Array.isArray(VX.row_zoom_windows) && VX.row_zoom_windows.length){
        const backdrop=document.querySelector("#vxRowZoomBackdrop");
        const stage=document.querySelector("#vxRowZoomStage");
        const active=VX.row_zoom_windows.find(w=>t>=w.at && t<w.end);

        if(backdrop && stage){
            if(active){
                const age=t-active.at, remain=active.end-t;
                const vis=Math.min(ease(age/0.35),ease(remain/0.35));
                const scale=0.001+0.999*vis;

                backdrop.style.opacity=String(vis*0.72/0.72*vis);
                backdrop.style.pointerEvents="none";
                stage.style.opacity=String(vis);
                stage.style.transform=`translate(-50%,-50%) scale(${scale})`;

                if(stage.dataset.activeTeam!==active.team){
                    const source=document.querySelector(`.team-row[data-team="${active.team}"]`);
                    if(source){
                        stage.innerHTML=source.outerHTML;
                        document.querySelectorAll(".team-row.vx-row-source-hidden")
                            .forEach(el=>el.classList.remove("vx-row-source-hidden"));
                        source.classList.add("vx-row-source-hidden");
                        stage.dataset.activeTeam=active.team;
                    }
                }
            }else{
                backdrop.style.opacity="0";
                stage.style.opacity="0";
                stage.style.transform="translate(-50%,-50%) scale(0.001)";
                if(stage.dataset.activeTeam){
                    document.querySelectorAll(".team-row.vx-row-source-hidden")
                        .forEach(el=>el.classList.remove("vx-row-source-hidden"));
                    stage.dataset.activeTeam="";
                    stage.innerHTML="";
                }
            }
        }
    }
    /* data-driven dead-air teaser */
    const teaser=document.querySelector("#vxDeadAirTeaser");
    if(teaser && Array.isArray(VX.teasers)){
        const active=VX.teasers.find(x=>t>=x.at && t<x.end);
        if(active){
            const age=t-active.at;
            const remain=active.end-t;
            const fadeIn=ease(age/0.45);
            const fadeOut=ease(remain/0.45);
            const vis=Math.min(fadeIn,fadeOut);
            teaser.style.opacity=String(vis);
            teaser.style.transform=`translateY(${(1-vis)*18}px) scale(${.985+.015*vis})`;

            const textEl=teaser.querySelector(".vxFactText");
            if(textEl){
                const full=String(active.text||"");
                const typeP=clamp(age/0.95);
                const n=Math.floor(full.length*typeP);
                textEl.textContent=full.slice(0,n)+(typeP<1 ? "▌" : "");
            }
        }else{
            teaser.style.opacity="0";
            teaser.style.transform="translateY(18px) scale(.985)";
            const textEl=teaser.querySelector(".vxFactText");
            if(textEl) textEl.textContent="";
        }
    }

    /* ----------------------------------------------------
       OUTRO STAGING
       ---------------------------------------------------- */

    if(VX.key==="05_outro" && VX.outro){

        const summary=document.querySelector("#summaryStage");
        const today=document.querySelector("#todayPanel");
        const cta=document.querySelector("#ctaStage");
        const logo=document.querySelector("#logoStage");
        const bgFade=document.querySelector("#bgFade");
        const logoHolder=document.querySelector("#logoStage .logoHolder");
        const logoImg=document.querySelector("#logoStage .vortex-logo, #logoStage img");

        const summaryOut=ease((t-VX.outro.ctaStart)/0.55);
        const ctaIn=ease((t-VX.outro.ctaStart)/0.55);
        const ctaOut=ease((t-VX.outro.logoStart)/0.42);
        const logoIn=ease((t-VX.outro.logoStart)/0.72);
        const dark=ease((t-VX.outro.tomorrowStart)/0.45);

        if(summary){
            summary.style.opacity=String(1-summaryOut);
            summary.style.transform=`translateY(${summaryOut*16}px)`;
        }
        if(today){
            today.style.filter=`brightness(${1-0.18*dark}) saturate(${1-0.08*dark})`;
        }
        if(cta){
            const ctaOpacity=Math.max(0, ctaIn*(1-ctaOut));
            cta.style.opacity=String(ctaOpacity);
            cta.style.transform=`translateY(${(1-ctaIn)*24 - ctaOut*8}px)`;
        }
        if(bgFade){bgFade.style.opacity=String(0.96*logoIn);}
        if(logo){
            logo.style.opacity=String(logoIn);
            logo.style.transform=`translateY(${(1-logoIn)*16}px)`;
        }
        if(logoHolder){
            const settle=clamp((t-VX.outro.logoStart)/1.25);
            const scale=1.05 - 0.05*settle;
            logoHolder.style.transform=`scale(${scale})`;
        }
        if(logoImg){
            const age=Math.max(0,t-VX.outro.logoStart);
            const shake=age<1.15 ? Math.sin(age*28)*(1-age/1.15)*8 : 0;
            logoImg.style.transform=`translateX(${shake}px)`;
        }
    }

    document.documentElement.dataset.vortexTime=
      t.toFixed(3);

    return t;
};

window.__auditLayout=function(t){

    window.__seek(t);

    return {
        time:t,
        viewport:[innerWidth,innerHeight],
        scroll:[
          document.documentElement.scrollWidth,
          document.documentElement.scrollHeight
        ]
    };
};

if(document.readyState==="loading")
    document.addEventListener("DOMContentLoaded",initVX);
else
    initVX();

</script>
<!-- VX_SHARED_END -->
"""

# ------------------------------------------------------------
# BUILD FIVE ANIMATED SCENES
# ------------------------------------------------------------

manifest={}

for key,(src_name,out_name) in SCENES.items():

    src=HTML/src_name
    out=ANIM/out_name

    if not src.exists():
        raise FileNotFoundError(f"Missing {src}")

    info=narr[key]
    words=info["words"]
    script=info["script"]
    duration=float(info["duration"])

    events=events_for(key,info)

    # Fill genuine dead-air: if meaningful body content is more than ~3s away, show a data teaser.
    if key=="00_intro":
        _body_candidates=[
            e for e in events
            if ".agenda-1" in e["sel"]
        ]
        _body_event=min(_body_candidates, key=lambda e: float(e["at"])) if _body_candidates else None
    elif key in {"02_fdr","03_projected_goals","04_clean_sheets"}:
        _body_event=next((e for e in events if ".panel" in e["sel"] or ".board" in e["sel"]), None)
    else:
        _body_event=next((e for e in events if "#todayPanel" in e["sel"]), None)

    _body_start=float(_body_event["at"]) if _body_event else 0.0
    teasers=[]
    fixture_grid_window=None

    if key=="00_intro":
        _fixture_event=next((e for e in events if ".fxGrid" in e["sel"]), None)
        if _fixture_event is None:
            raise RuntimeError("00_intro fixture event is missing")
        fixture_at=float(_fixture_event["at"])
        fixture_grid_window={
            "at":round(fixture_at,3),
            "end":round(_body_start,3),
        }
        if fixture_grid_window["end"] <= fixture_grid_window["at"]:
            raise RuntimeError(f"Invalid intro fixture window: {fixture_grid_window}")

    if key!="00_intro" and _body_start >= 3.2:
        _facts=list(SCENE_DEAD_AIR_FACTS.get(key, []))
        _start=0.65
        _end=max(_start, _body_start-1.0)
        _available=_end-_start

        if _facts and _available >= 2.1:
            _count=2 if len(_facts) >= 2 and _available >= 5.8 else 1
            _slot=_available/_count
            for _i in range(_count):
                _at=_start+(_i*_slot)
                _teaser_end=min(_end, _at+_slot-0.18)
                if _teaser_end-_at >= 1.8:
                    teasers.append({
                        "text":str(_facts[_i]),
                        "at":round(_at,3),
                        "end":round(_teaser_end,3),
                    })

    # Team highlight occurs exactly when Ryan says name
    highlights=[]

    for team in TEAM_NAMES:

        if vx_norm_text(team) not in vx_norm_text(script):
            continue

        t=vx_phrase_time(words,team,-1)

        if t>=0:
            highlights.append({
                "text":team,
                "at":round(t,3)
            })

    vx={
        "key":key,
        "duration":duration,
        "events":events,
        "highlights":highlights,
        "teasers":teasers,
        "fixture_grid_window":fixture_grid_window,
        "logo":OUTRO_LOGO_URI
    }
    # Outro timings are strict Ryan WordBoundary anchors — no guessed fallbacks.
    if key=="05_outro":

        today_1=vx_phrase_time(words,"best fixture runs",required=True,context="05_outro recap")
        today_2=vx_phrase_time(words,"strongest projected output",required=True,context="05_outro recap")
        today_3=vx_phrase_time(words,"highest clean-sheet potential",required=True,context="05_outro recap")
        tomorrow=vx_phrase_time(words,"Tomorrow",required=True,context="05_outro tomorrow panel")
        cta_start=vx_phrase_time(words,"Subscribe and follow",required=True,context="05_outro CTA")
        logo_phrase_start=vx_phrase_time(words,"Let us make smarter",required=True,context="05_outro logo finale")
        minimum_logo_hold=3.25
        logo_start=min(logo_phrase_start,max(0.0,duration-minimum_logo_hold))
        logo_start=max(logo_start,cta_start+1.20)
        logo_hold=duration-logo_start
        if logo_hold < 2.50:
            raise RuntimeError(
                f"05_outro final logo hold is too short: {logo_hold:.2f}s"
            )

        vx["outro"]={
            "today1":today_1,
            "today2":today_2,
            "today3":today_3,
            "tomorrowStart":tomorrow,
            "ctaStart":cta_start,
            "logoPhraseStart":logo_phrase_start,
            "logoStart":logo_start,
            "logoHold":logo_hold,
            "minimumLogoHold":minimum_logo_hold,
        }

        highlights += [
            {"text":"Best Fixtures","at":round(today_1,3)},
            {"text":"Best Projected Attack","at":round(today_2,3)},
            {"text":"Best Clean-Sheet Odds","at":round(today_3,3)},
            {"text":"Safe Core Picks","at":round(vx_phrase_time(words,"safe core picks",required=True,context="05_outro agenda"),3)},
            {"text":"Rank-Climb Options","at":round(vx_phrase_time(words,"rank-climb options",required=True,context="05_outro agenda"),3)},
            {"text":"Player Traps","at":round(vx_phrase_time(words,"player traps",required=True,context="05_outro agenda"),3)},
            {"text":"Captaincy","at":round(vx_phrase_time(words,"captaincy",required=True,context="05_outro agenda"),3)},
            {"text":"Transfer Plan","at":round(vx_phrase_time(words,"transfer plan",required=True,context="05_outro agenda"),3)},
        ]

    page=src.read_text(
        encoding="utf-8",
        errors="ignore"
    )

    # clean old shared injection
    page=re.sub(
        r"<!-- VX_SHARED_START -->.*?"
        r"<!-- VX_SHARED_END -->",
        "",
        page,
        flags=re.S
    )

    page=page.replace(
        "</head>",
        CSS+"\n</head>"
    )

    page=page.replace(
        "</body>",
        JS.replace(
            "__VX__",
            json.dumps(vx,ensure_ascii=False)
        )+"\n</body>"
    )

    out.write_text(
        page,
        encoding="utf-8"
    )

    manifest[key]={
        "html":str(out),
        "audio":info["audio"],
        "duration":duration,
        "canvas":[3840,2160],
        "highlights":highlights,
        "events":events,
        "teasers":teasers,
        "fixture_grid_window":fixture_grid_window
    }

    print(
        f"✅ {key:<20}"
        f"{duration:>6.2f}s • "
        f"{len(highlights)} spoken highlights • "
        f"{len(teasers)} dead-air facts"
    )

# ------------------------------------------------------------
# SAVE
# ------------------------------------------------------------

OUT=TIMING/"other_scenes_animation.json"

OUT.write_text(
    json.dumps(manifest,indent=2),
    encoding="utf-8"
)

print("\n" + "="*62)
print("✅ CELL 19 COMPLETE")
print("="*62)
print("✅ Intro animated")
print("✅ FDR animated")
print("✅ Projected Goals animated")
print("✅ Clean Sheet Odds animated")
print("✅ Outro animated")
print("✅ Intro + Outro exact Ryan WordBoundary sync")
print("✅ All locked 3840 × 2160")
print("✅ Spoken-team highlighting")
print("✅ Outro footer matches Intro")
print("✅ Subscribe + follow CTA")
print("✅ Original-logo growl finale")
print("✅ Intro sequence: blank centre → centered fixtures → agenda 01–04 one by one")
print("✅ Each agenda title and short description reveal together as one card")
print("✅ Intro fixture board is fully removed before agenda 01")
print("✅ Outro finale has a protected visible tail hold")

# ============================================================
# CELL 20 — RESUME-SAFE SHARED MP4 RENDERER
# Event-aware Chromium keyframes → FFmpeg CFR master
# Cell 0 controls selected scenes + Draft 480p5 / Final true 4K 2160p24
# ============================================================

from pathlib import Path
import hashlib
import json
import math
import os
import shutil
import subprocess
import sys
from IPython.display import display, Image as IPImage

ROOT       = Path(globals().get("PROJECT_ROOT", "/content/drive/MyDrive/FPL_VORTEX"))
TIMING     = Path(globals().get("DATA_DIR", "/content/FPL_VORTEX_FIRST_DAY_WORK/data"))
SECTIONS   = Path(globals().get("MP4_DIR", "/content/FPL_VORTEX_FIRST_DAY_WORK/mp4"))
PREVIEWS   = Path(globals().get("PREVIEW_WORK_DIR", "/content/FPL_VORTEX_FIRST_DAY_WORK/preview"))
VIDEO_WORK = Path(globals().get("VIDEO_WORK_DIR", "/content/FPL_VORTEX_FIRST_DAY_WORK/video"))
KEYFRAME_DIR = VIDEO_WORK / "cell20_keyframes"

for _directory in (TIMING, SECTIONS, PREVIEWS, VIDEO_WORK, KEYFRAME_DIR):
    _directory.mkdir(parents=True, exist_ok=True)

if not str(KEYFRAME_DIR.resolve()).startswith("/content/"):
    raise RuntimeError(f"Cell 20 temporary work must stay in /content: {KEYFRAME_DIR}")

ORDER = [
    key for key in [
        "00_intro",
        "02_fdr",
        "03_projected_goals",
        "04_clean_sheets",
        "05_outro",
    ]
    if globals().get("SLIDE_SELECTION", {}).get(key, True)
]

MANIFEST = TIMING / "other_scenes_animation.json"
if ORDER and not MANIFEST.exists():
    raise FileNotFoundError("Run Cell 19 first — shared-scene manifest is missing.")

SCENES = json.loads(MANIFEST.read_text(encoding="utf-8")) if ORDER else {}

# ------------------------------------------------------------
# DESIGN / OUTPUT CONTRACT
# ------------------------------------------------------------

DESIGN_W, DESIGN_H = 3840, 2160
W = int(globals().get("VIDEO_WIDTH", 3840))
H = int(globals().get("VIDEO_HEIGHT", 2160))
FPS = int(globals().get("VIDEO_FPS", 30))
SCALE_X = W / DESIGN_W
SCALE_Y = H / DESIGN_H

if W <= 0 or H <= 0 or FPS <= 0:
    raise ValueError(f"Invalid Cell 20 output: {W}x{H} at {FPS}fps")

for _helper in ("vx_media_duration", "vx_frame_plan", "vx_video_info", "vx_apply_render_scale"):
    if _helper not in globals():
        raise RuntimeError(f"Run Cell 9 first — shared helper {_helper} is missing.")

RENDERER_VERSION = "VX20-EVENT-KEYFRAMES-V1"
SCENE_RENDER_REVISIONS = {
    "00_intro": "VX20-INTRO-CENTERED-FIXTURES-V4-18S-MIXED-REVIEW",
    "05_outro": "VX20-OUTRO-VISIBLE-TAIL-V4-MIXED-REVIEW",
}
RESUME = bool(globals().get("RESUME_EXISTING_MP4", True))
FORCE = bool(globals().get("FORCE_RERENDER", False))

# Chromium is sampled only while something is actually moving. FFmpeg supplies
# the requested constant output frame rate. Static narration holds cost no
# browser screenshots.
MOTION_CAPTURE_FPS = int(
    globals().get("CELL20_MOTION_CAPTURE_FPS", 12 if FPS > 5 else FPS)
)
MOTION_CAPTURE_FPS = max(1, min(MOTION_CAPTURE_FPS, max(FPS, 12)))
JPEG_QUALITY = int(globals().get("CELL20_JPEG_QUALITY", 94))
JPEG_QUALITY = max(80, min(JPEG_QUALITY, 100))

CACHE_FILE = TIMING / "cell20_scene_cache.json"
REPORT_FILE = TIMING / "other_scenes_render.json"


# ------------------------------------------------------------
# SMALL, CELL-LOCAL HELPERS — NO SECOND RENDER PATH
# ------------------------------------------------------------

def _vx20_sha256(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _vx20_parse_fps(value):
    try:
        num, den = str(value).split("/", 1)
        den = float(den)
        return float(num) / den if den else 0.0
    except Exception:
        return 0.0


def _vx20_probe(path):
    run = subprocess.run(
        [
            "ffprobe", "-v", "error", "-print_format", "json",
            "-show_format", "-show_streams", str(path),
        ],
        capture_output=True,
        text=True,
        check=True,
    )
    return json.loads(run.stdout)


def _vx20_valid_mp4(path, grid_duration):
    path = Path(path)
    if not path.exists() or path.stat().st_size < 20_000:
        return False, None
    try:
        info = _vx20_probe(path)
        streams = info.get("streams", [])
        video = next(s for s in streams if s.get("codec_type") == "video")
        audio = next(s for s in streams if s.get("codec_type") == "audio")
        actual_fps = _vx20_parse_fps(
            video.get("avg_frame_rate") or video.get("r_frame_rate")
        )
        duration = float(info["format"]["duration"])
        tolerance = max(0.12, 2.0 / FPS)
        valid = (
            int(video.get("width", 0)) == W
            and int(video.get("height", 0)) == H
            and abs(actual_fps - FPS) <= 0.05
            and video.get("codec_name") == "h264"
            and audio.get("codec_name") == "aac"
            and abs(duration - grid_duration) <= tolerance
        )
        return valid, {
            "duration": duration,
            "width": int(video.get("width", 0)),
            "height": int(video.get("height", 0)),
            "fps": actual_fps,
            "video_codec": video.get("codec_name"),
            "audio_codec": audio.get("codec_name"),
        }
    except Exception:
        return False, None


def _vx20_atomic_json(path, payload):
    path = Path(path)
    temp = path.with_name(f".{path.name}.tmp")
    temp.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    os.replace(temp, path)


def _vx20_extract_preview(video, preview, duration):
    preview = Path(preview)
    preview.parent.mkdir(parents=True, exist_ok=True)
    subprocess.run(
        [
            "ffmpeg", "-y", "-v", "error",
            "-ss", f"{max(0.0, duration - 0.20):.6f}",
            "-i", str(video),
            "-frames:v", "1", str(preview),
        ],
        check=True,
    )


def _vx20_fingerprint(key, cfg, html, audio, duration):
    payload = {
        "renderer": RENDERER_VERSION,
        "scene": key,
        "html_sha256": _vx20_sha256(html),
        "audio_sha256": _vx20_sha256(audio),
        "duration": round(float(duration), 6),
        "width": W,
        "height": H,
        "fps": FPS,
        "motion_capture_fps": MOTION_CAPTURE_FPS,
        "jpeg_quality": JPEG_QUALITY,
        "events": cfg.get("events", []),
        "highlights": cfg.get("highlights", []),
        "teasers": cfg.get("teasers", []),
        "fixture_grid_window": cfg.get("fixture_grid_window"),
    }
    if key in SCENE_RENDER_REVISIONS:
        payload["scene_revision"] = SCENE_RENDER_REVISIONS[key]
    encoded = json.dumps(
        payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _vx20_add_window(times, start, end, last_t):
    pad = 1.0 / max(FPS, 1)
    start = max(0.0, float(start) - pad)
    end = min(float(last_t), max(start, float(end) + pad))
    if end <= start:
        times.add(round(start, 6))
        return
    steps = max(1, int(math.ceil((end - start) * MOTION_CAPTURE_FPS)))
    for index in range(steps + 1):
        times.add(round(start + (end - start) * index / steps, 6))


async def _vx20_sample_times(page, cfg, duration, frame_plan):
    last_t = max(0.0, (int(frame_plan["frames"]) - 1) / FPS)
    times = {0.0, round(last_t, 6), round(float(frame_plan["grid_duration"]), 6)}

    events = list(cfg.get("events", []))
    selector_counts = await page.evaluate(
        """
        events => events.map(event => {
            try { return document.querySelectorAll(event.sel).length; }
            catch (_) { return 0; }
        })
        """,
        events,
    )

    for event, count in zip(events, selector_counts):
        at = float(event.get("at", 0.0))
        dur = max(0.28, float(event.get("dur", 0.65)))
        stagger = max(0.0, float(event.get("stagger", 0.0)))
        span = dur + max(0, int(count) - 1) * stagger
        _vx20_add_window(times, at, at + span, last_t)

    for highlight in cfg.get("highlights", []):
        at = float(highlight.get("at", 0.0))
        _vx20_add_window(times, at, at + 1.15, last_t)

    for teaser in cfg.get("teasers", []):
        start = float(teaser.get("at", 0.0))
        end = float(teaser.get("end", start))
        _vx20_add_window(times, start, min(end, start + 1.05), last_t)
        _vx20_add_window(times, max(start, end - 0.50), end, last_t)
        if end > start:
            times.add(round(min(last_t, (start + end) / 2.0), 6))


    fixture_window = cfg.get("fixture_grid_window")
    if isinstance(fixture_window, dict):
        start = float(fixture_window.get("at", 0.0))
        end = float(fixture_window.get("end", start))
        _vx20_add_window(times, start, min(end, start + 0.60), last_t)
        _vx20_add_window(times, max(start, end - 0.55), end, last_t)
        if end > start:
            times.add(round(min(last_t, (start + end) / 2.0), 6))

    vx_timing = await page.evaluate(
        """
        () => {
            const vx = (typeof VX !== "undefined") ? VX : (window.VX || {});
            return {outro: vx.outro || null};
        }
        """
    )
    outro = vx_timing.get("outro") if isinstance(vx_timing, dict) else None
    if isinstance(outro, dict):
        for field, span in (("tomorrowStart", 0.55), ("ctaStart", 0.70), ("logoStart", 1.35)):
            if field in outro:
                at = float(outro[field])
                _vx20_add_window(times, at, at + span, last_t)

    return sorted(t for t in times if 0.0 <= t <= float(frame_plan["grid_duration"]) + 1e-6)


def _vx20_concat_quote(path):
    return str(Path(path).resolve()).replace("'", "'\\''")


def _vx20_publish(local_final, final):
    final = Path(final)
    uploading = final.with_name(f".{final.stem}.uploading.mp4")
    uploading.unlink(missing_ok=True)
    shutil.copy2(local_final, uploading)
    os.replace(uploading, final)


# ------------------------------------------------------------
# PLAN EACH SCENE BEFORE STARTING CHROMIUM
# ------------------------------------------------------------

try:
    CACHE = json.loads(CACHE_FILE.read_text(encoding="utf-8")) if CACHE_FILE.exists() else {}
except Exception:
    CACHE = {}

RENDERED = {}
PENDING = []

for key in ORDER:
    if key not in SCENES:
        raise KeyError(f"Cell 19 manifest missing {key}")

    cfg = SCENES[key]
    html = Path(cfg["html"])
    audio = Path(cfg["audio"])
    if not html.exists():
        raise FileNotFoundError(html)
    if not audio.exists():
        raise FileNotFoundError(audio)

    duration = vx_media_duration(audio)
    expected = float(cfg["duration"])
    if abs(duration - expected) > 0.30:
        raise RuntimeError(
            f"{key}: audio/timeline mismatch {duration:.3f}s vs {expected:.3f}s"
        )

    frame_plan = vx_frame_plan(duration, FPS)
    final = SECTIONS / f"{key}.mp4"
    preview = PREVIEWS / f"{key}_{H}p.png"
    fingerprint = _vx20_fingerprint(key, cfg, html, audio, duration)
    valid, media = _vx20_valid_mp4(final, float(frame_plan["grid_duration"]))
    cached_fingerprint = (CACHE.get(key) or {}).get("fingerprint")
    fingerprint_matches = cached_fingerprint == fingerprint
    if RESUME and not FORCE and valid and fingerprint_matches:
        if not preview.exists():
            _vx20_extract_preview(final, preview, float(media["duration"]))
        status = "reused"
        print(f"♻️ {key}: valid fingerprint-matching MP4 reused — Chromium render skipped")
        RENDERED[key] = {
            "key": key,
            "final": str(final),
            "preview": str(preview),
            "duration": float(media["duration"]),
            "width": W,
            "height": H,
            "fps": FPS,
            "status": status,
            "fingerprint": fingerprint,
            "browser_keyframes": 0,
            "output_frames": int(frame_plan["frames"]),
        }
        CACHE[key] = {
            "fingerprint": fingerprint,
            "final": str(final),
            "duration": float(media["duration"]),
            "width": W,
            "height": H,
            "fps": FPS,
            "renderer": RENDERER_VERSION,
        }
        _vx20_atomic_json(CACHE_FILE, CACHE)
    else:
        if final.exists() and not FORCE:
            reason = "source/settings changed" if valid else "output failed QA"
            print(f"🔄 {key}: {reason} — rerendering")
        PENDING.append({
            "key": key,
            "cfg": cfg,
            "html": html,
            "audio": audio,
            "duration": duration,
            "frame_plan": frame_plan,
            "final": final,
            "preview": preview,
            "fingerprint": fingerprint,
        })


# ------------------------------------------------------------
# ONE BROWSER, ONE PAGE, ONLY FOR SCENES THAT NEED WORK
# ------------------------------------------------------------

async def _vx20_render_scene(page, job):
    key = job["key"]
    cfg = job["cfg"]
    html = job["html"]
    audio = job["audio"]
    duration = float(job["duration"])
    frame_plan = job["frame_plan"]
    frames = int(frame_plan["frames"])
    grid_duration = float(frame_plan["grid_duration"])
    final = job["final"]
    preview = job["preview"]

    scene_work = KEYFRAME_DIR / key
    scene_work.mkdir(parents=True, exist_ok=True)
    for stale in scene_work.glob("frame_*.jpg"):
        stale.unlink(missing_ok=True)
    for stale_name in ("frames.ffconcat", "silent.mp4", "muxed.mp4"):
        (scene_work / stale_name).unlink(missing_ok=True)

    print("\n" + "=" * 70)
    print(f"🎬 {key}")
    print(f"🎨 Design  : {DESIGN_W}x{DESIGN_H}")
    print(f"📺 Output  : {W}x{H} at {FPS}fps")
    print(f"🎙 Audio   : {duration:.2f}s")
    print(f"🎞 Output frames: {frames:,}")
    print("=" * 70)

    await page.goto(html.resolve().as_uri(), wait_until="load", timeout=120000)
    await page.wait_for_function("window.__ready === true", timeout=60000)
    await vx_apply_render_scale(page, W, H, DESIGN_W, DESIGN_H)

    try:
        await page.evaluate("() => document.fonts.ready")
    except Exception:
        pass
    try:
        await page.wait_for_function(
            "() => Array.from(document.images).every(img => img.complete)",
            timeout=15000,
        )
    except Exception:
        print("⚠️ Continuing after image wait timeout.")

    audit = await page.evaluate(
        """
        () => {
            const b = document.body.getBoundingClientRect();
            return {
                viewport: [innerWidth, innerHeight],
                body: [Math.round(b.left), Math.round(b.top), Math.round(b.width), Math.round(b.height)]
            };
        }
        """
    )
    if audit["viewport"] != [W, H] or audit["body"] != [0, 0, W, H]:
        raise RuntimeError(f"{key}: full-bleed audit failed: {audit}")

    sample_times = await _vx20_sample_times(page, cfg, duration, frame_plan)
    print(
        f"🪶 Browser keyframes: {len(sample_times):,} "
        f"instead of {frames:,} full PNG screenshots"
    )

    frame_paths = []
    report_every = max(1, len(sample_times) // 20)
    for index, timeline_t in enumerate(sample_times):
        seek_t = min(float(timeline_t), max(0.0, duration - 1.0 / FPS))
        await page.evaluate("t => window.__seek(t)", seek_t)
        frame_path = scene_work / f"frame_{index:06d}.jpg"
        await page.screenshot(
            path=str(frame_path),
            type="jpeg",
            quality=JPEG_QUALITY,
        )
        frame_paths.append(frame_path)
        if index % report_every == 0 or index == len(sample_times) - 1:
            pct = (index + 1) / len(sample_times) * 100
            print(
                f"\rCapturing motion {pct:5.1f}% "
                f"({index + 1:,}/{len(sample_times):,})",
                end="",
            )
    print()

    preview_t = max(0.05, duration - 0.20)
    await page.evaluate("t => window.__seek(t)", preview_t)
    await page.screenshot(path=str(preview), type="png")

    concat_lines = ["ffconcat version 1.0"]
    for index in range(len(frame_paths) - 1):
        delta = max(1e-6, sample_times[index + 1] - sample_times[index])
        concat_lines.append(f"file '{_vx20_concat_quote(frame_paths[index])}'")
        concat_lines.append(f"duration {delta:.9f}")
    concat_lines.append(f"file '{_vx20_concat_quote(frame_paths[-1])}'")
    concat_lines.append(f"file '{_vx20_concat_quote(frame_paths[-1])}'")

    concat_file = scene_work / "frames.ffconcat"
    concat_file.write_text("\n".join(concat_lines) + "\n", encoding="utf-8")
    silent = scene_work / "silent.mp4"
    local_final = scene_work / "muxed.mp4"

    subprocess.run(
        [
            "ffmpeg", "-y", "-v", "error",
            "-f", "concat", "-safe", "0", "-i", str(concat_file),
            "-an",
            "-vf", f"fps={FPS}:round=near,format=yuv420p",
            "-frames:v", str(frames),
            "-c:v", "libx264", "-preset", "veryfast", "-crf", "18",
            "-pix_fmt", "yuv420p", "-movflags", "+faststart",
            str(silent),
        ],
        check=True,
    )

    subprocess.run(
        [
            "ffmpeg", "-y", "-v", "error",
            "-i", str(silent), "-i", str(audio),
            "-map", "0:v:0", "-map", "1:a:0",
            "-c:v", "copy",
            "-c:a", "aac", "-b:a", "192k", "-ar", "48000",
            "-af", "apad",
            "-t", f"{grid_duration:.9f}",
            "-movflags", "+faststart",
            str(local_final),
        ],
        check=True,
    )

    valid, media = _vx20_valid_mp4(local_final, grid_duration)
    if not valid:
        raise RuntimeError(f"{key}: local MP4 failed publish QA: {media}")

    _vx20_publish(local_final, final)
    valid, published_media = _vx20_valid_mp4(final, grid_duration)
    if not valid:
        raise RuntimeError(f"{key}: Drive MP4 failed read-back QA: {published_media}")

    CACHE[key] = {
        "fingerprint": job["fingerprint"],
        "final": str(final),
        "duration": float(published_media["duration"]),
        "width": W,
        "height": H,
        "fps": FPS,
        "renderer": RENDERER_VERSION,
        "browser_keyframes": len(sample_times),
        "output_frames": frames,
    }
    _vx20_atomic_json(CACHE_FILE, CACHE)

    # Only local /content keyframes are removed. The completed Drive MP4 stays.
    for temporary in frame_paths + [concat_file, silent, local_final]:
        Path(temporary).unlink(missing_ok=True)

    print(
        f"✅ {key}: {W}x{H} at {FPS}fps, "
        f"{published_media['duration']:.2f}s — published and cached"
    )
    return {
        "key": key,
        "final": str(final),
        "preview": str(preview),
        "duration": float(published_media["duration"]),
        "width": W,
        "height": H,
        "fps": FPS,
        "status": "rendered",
        "fingerprint": job["fingerprint"],
        "browser_keyframes": len(sample_times),
        "output_frames": frames,
    }


async def _vx20_render_pending():
    if not PENDING:
        print("✅ Cell 20: every selected shared scene is already complete.")
        return

    if "_vx_ensure_playwright_chromium" not in globals() or "async_playwright" not in globals():
        raise RuntimeError("Run Cell 14 first — shared Playwright renderer is missing.")
    _vx_ensure_playwright_chromium()

    async with async_playwright() as playwright:
        try:
            browser = await playwright.chromium.launch(
                headless=True,
                args=["--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu"],
            )
        except Exception:
            subprocess.run(
                [sys.executable, "-m", "playwright", "install", "chromium"],
                check=True,
            )
            browser = await playwright.chromium.launch(
                headless=True,
                args=["--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu"],
            )

        context = await browser.new_context(
            viewport={"width": W, "height": H},
            device_scale_factor=1,
        )
        page = await context.new_page()
        try:
            for job in PENDING:
                RENDERED[job["key"]] = await _vx20_render_scene(page, job)
        finally:
            await context.close()
            await browser.close()


await _vx20_render_pending()

# Preserve Cell 0 order even when results were a mixture of reused/rendered.
RENDERED = {key: RENDERED[key] for key in ORDER}
_vx20_atomic_json(REPORT_FILE, RENDERED)


