def _vx21_probe(path):
    run = subprocess.run(
        [
            "ffprobe", "-v", "error", "-print_format", "json",
            "-show_format", "-show_streams", str(path),
        ],
        capture_output=True,
        text=True,
        check=True,
    )
    return json.loads(run.stdout)


def _vx21_fps(value):
    try:
        num, den = str(value).split("/", 1)
        den = float(den)
        return float(num) / den if den else 0.0
    except Exception:
        return 0.0


def _vx21_quick_hash(path, chunk_size=1024 * 1024):
    """Hash size + first/last MiB so resume checks do not reread multi-GB MP4s."""
    path = Path(path)
    size = path.stat().st_size
    digest = hashlib.sha256()
    digest.update(str(size).encode("ascii"))
    with path.open("rb") as handle:
        digest.update(handle.read(chunk_size))
        if size > chunk_size:
            handle.seek(max(0, size - chunk_size))
            digest.update(handle.read(chunk_size))
    return digest.hexdigest()


def _vx21_atomic_json(path, payload):
    path = Path(path)
    temporary = path.with_name(f".{path.name}.tmp")
    temporary.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    os.replace(temporary, path)


def _vx21_atomic_publish(local_path, drive_path):
    local_path = Path(local_path)
    drive_path = Path(drive_path)
    uploading = drive_path.with_name(f".{drive_path.stem}.uploading{drive_path.suffix}")
    uploading.unlink(missing_ok=True)
    shutil.copy2(local_path, uploading)
    os.replace(uploading, drive_path)


def _vx21_stream_signature(video, audio):
    return (
        video.get("codec_name"),
        video.get("profile"),
        video.get("pix_fmt"),
        int(video.get("width", 0)),
        int(video.get("height", 0)),
        video.get("avg_frame_rate"),
        video.get("time_base"),
        audio.get("codec_name"),
        audio.get("sample_fmt"),
        str(audio.get("sample_rate")),
        int(audio.get("channels", 0)),
        audio.get("channel_layout"),
        audio.get("time_base"),
    )


def _vx21_master_valid(path, expected_duration):
    path = Path(path)
    if not path.exists() or path.stat().st_size < 50_000:
        return False, None
    try:
        info = _vx21_probe(path)
        streams = info.get("streams", [])
        video = next(s for s in streams if s.get("codec_type") == "video")
        audio = next(s for s in streams if s.get("codec_type") == "audio")
        duration = float(info["format"]["duration"])
        fps = _vx21_fps(video.get("avg_frame_rate") or video.get("r_frame_rate"))
        valid = (
            int(video.get("width", 0)) == W
            and int(video.get("height", 0)) == H
            and abs(fps - FPS) <= 0.05
            and video.get("codec_name") == "h264"
            and audio.get("codec_name") == "aac"
            and abs(duration - expected_duration) <= 0.75
        )
        return valid, {
            "duration": duration,
            "width": int(video.get("width", 0)),
            "height": int(video.get("height", 0)),
            "fps": fps,
            "video_codec": video.get("codec_name"),
            "audio_codec": audio.get("codec_name"),
            "video": video,
            "audio": audio,
        }
    except Exception:
        return False, None


def _vx21_mp3_valid(path, expected_duration):
    path = Path(path)
    if not path.exists() or path.stat().st_size < 10_000:
        return False, None
    try:
        info = _vx21_probe(path)
        audio = next(s for s in info.get("streams", []) if s.get("codec_type") == "audio")
        duration = float(info["format"]["duration"])
        valid = audio.get("codec_name") == "mp3" and abs(duration - expected_duration) <= 0.25
        return valid, {"duration": duration, "audio_codec": audio.get("codec_name")}
    except Exception:
        return False, None


def _vx21_concat_quote(path):
    return str(Path(path).resolve()).replace("'", "'\\''")


# Remove only known atomic-publish leftovers. They are incomplete hidden copies,
# never completed scene/master outputs.
for _uploading in list(VIDEO.glob(".*.uploading.mp4")) + list(MP3_OUT.glob(".*.uploading.mp3")):
    _uploading.unlink(missing_ok=True)


# ------------------------------------------------------------
# VALIDATE SELECTED COMPLETED SCENES — NEVER RENDER THEM HERE
# ------------------------------------------------------------

reports = []
signatures = []
source_fingerprints = []
expected_duration = 0.0

print("=" * 74)
print(f"🔍 FINAL SELECTED-SCENE QA — {len(ORDER)} scene(s)")
print("=" * 74)

for number, (key, label, path) in enumerate(ORDER, 1):
    if not path.exists():
        raise FileNotFoundError(
            f"{label} is missing: {path}\n"
            "Cell 21 only assembles completed MP4s; run its owning render cell first."
        )

    info = _vx21_probe(path)
    streams = info.get("streams", [])
    video = next((s for s in streams if s.get("codec_type") == "video"), None)
    audio = next((s for s in streams if s.get("codec_type") == "audio"), None)
    if video is None:
        raise RuntimeError(f"{label}: video stream missing")
    if audio is None:
        raise RuntimeError(f"{label}: audio stream missing")

    width = int(video.get("width", 0))
    height = int(video.get("height", 0))
    fps = _vx21_fps(video.get("avg_frame_rate") or video.get("r_frame_rate"))
    duration = float(info["format"]["duration"])

    if (width, height) != (W, H):
        raise RuntimeError(f"{label}: {width}x{height} instead of {W}x{H}")
    if abs(fps - FPS) > 0.05:
        raise RuntimeError(f"{label}: {fps:.3f}fps instead of {FPS}fps")
    if duration <= 0:
        raise RuntimeError(f"{label}: invalid duration {duration}")

    stat = path.stat()
    quick_hash = _vx21_quick_hash(path)
    signature = _vx21_stream_signature(video, audio)
    signatures.append(signature)
    expected_duration += duration

    source_record = {
        "order": number,
        "key": key,
        "scene": label,
        "file": str(path),
        "size": stat.st_size,
        "quick_sha256": quick_hash,
        "duration": duration,
        "signature": list(signature),
    }
    source_fingerprints.append(source_record)
    reports.append({
        "order": number,
        "key": key,
        "scene": label,
        "file": str(path),
        "duration": duration,
        "resolution": [width, height],
        "fps": fps,
        "video_codec": video.get("codec_name"),
        "audio_codec": audio.get("codec_name"),
        "quick_sha256": quick_hash,
    })

    print(
        f"✅ {number}. {label:<18} {duration:>7.2f}s • "
        f"{width}x{height} • {fps:.0f}fps • "
        f"{video.get('codec_name')}/{audio.get('codec_name')}"
    )


fingerprint_payload = {
    "assembler": ASSEMBLER_VERSION,
    "quality": QUALITY_LOCAL,
    "width": W,
    "height": H,
    "fps": FPS,
    "selected_scenes": source_fingerprints,
}
ASSEMBLY_FINGERPRINT = hashlib.sha256(
    json.dumps(
        fingerprint_payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
).hexdigest()


# ------------------------------------------------------------
# PHASE-0 OUTPUT CONTRACT — BEFORE PUBLISH
# ------------------------------------------------------------

_ALLOWED_OUTPUT_DIRS = {
    "MP4": VIDEO,
    "MP3": MP3_OUT,
    "SLIDE": SLIDE_OUT,
    "DATA": DATA,
}


def _vx21_output_contract_violations():
    violations = []
    if OUTPUT.exists():
        for child in OUTPUT.iterdir():
            if child.is_dir() and child.name not in _ALLOWED_OUTPUT_DIRS:
                violations.append(f"unexpected_output_directory:{child.name}")
            elif child.is_file():
                violations.append(f"unexpected_root_file:{child.name}")

    if DATA.exists():
        for path in DATA.rglob("*"):
            if path.is_file() and path.suffix.lower() not in {".json", ".vtt"}:
                violations.append(f"invalid_data_artifact:{path.name}")

    for path in VIDEO.rglob("*") if VIDEO.exists() else []:
        if path.is_file() and path.suffix.lower() != ".mp4":
            violations.append(f"invalid_mp4_artifact:{path.name}")
        if path.is_file() and any(
            marker in path.name.lower() for marker in ("silent", "preview", "uploading")
        ):
            violations.append(f"temporary_video_in_drive:{path.name}")

    for path in MP3_OUT.rglob("*") if MP3_OUT.exists() else []:
        if path.is_file() and path.suffix.lower() != ".mp3":
            violations.append(f"invalid_mp3_artifact:{path.name}")
        if path.is_file() and any(
            marker in path.name.lower() for marker in ("segment", "temp", "uploading")
        ):
            violations.append(f"temporary_audio_in_drive:{path.name}")

    for path in SLIDE_OUT.rglob("*") if SLIDE_OUT.exists() else []:
        if path.is_file() and path.suffix.lower() not in {".png", ".jpg", ".jpeg", ".webp"}:
            violations.append(f"invalid_slide_artifact:{path.name}")

    if not (DATA / "phase0_audit.json").exists():
        violations.append("missing_required_phase0_data:phase0_audit.json")

    if "vx_phase0_assert_cleanroom" not in globals():
        violations.append("phase0_cleanroom_guard_missing")
    else:
        try:
            vx_phase0_assert_cleanroom("pre-publish")
        except Exception as exc:
            violations.append("phase0_cleanroom_fail:" + str(exc))
    return violations


_output_contract_violations = _vx21_output_contract_violations()
if _output_contract_violations:
    raise RuntimeError(
        "PHASE 0 OUTPUT CONTRACT FAILED:\n- "
        + "\n- ".join(_output_contract_violations)
    )


# ------------------------------------------------------------
# MASTER RESUME GATE
# ------------------------------------------------------------

try:
    MASTER_CACHE = json.loads(CACHE_FILE.read_text(encoding="utf-8")) if CACHE_FILE.exists() else {}
except Exception:
    MASTER_CACHE = {}

cache_entries = MASTER_CACHE.get("masters", {}) if isinstance(MASTER_CACHE, dict) else {}
cache_key = str(FINAL_MP4)
cached_fingerprint = (cache_entries.get(cache_key) or {}).get("fingerprint")
master_valid, master_media = _vx21_master_valid(FINAL_MP4, expected_duration)
REUSE_MASTER = (
    RESUME
    and not FORCE
    and master_valid
    and cached_fingerprint == ASSEMBLY_FINGERPRINT
)


# ------------------------------------------------------------
# ASSEMBLE LOCALLY ONLY WHEN THE MASTER IS STALE/MISSING
# ------------------------------------------------------------

if REUSE_MASTER:
    ASSEMBLY_MODE = "REUSED VALID MASTER"
    print(f"\n♻️ Final master already matches selected scene MP4s — SKIP ASSEMBLY")
    print(f"✅ {FINAL_MP4}")
else:
    LOCAL_MASTER.unlink(missing_ok=True)
    CONCAT_FILE.write_text(
        "ffconcat version 1.0\n"
        + "\n".join(
            f"file '{_vx21_concat_quote(path)}'" for _, _, path in ORDER
        )
        + "\n",
        encoding="utf-8",
    )

    streams_match = len(set(signatures)) == 1
    first_signature = signatures[0]
    stream_copy_safe = (
        streams_match
        and first_signature[0] == "h264"
        and first_signature[2] == "yuv420p"
        and first_signature[7] == "aac"
    )

    def _vx21_run_normalized_encode():
        inputs = []
        for _, _, path in ORDER:
            inputs += ["-i", str(path)]

        filters = []
        for index in range(len(ORDER)):
            filters.append(
                f"[{index}:v:0]scale={W}:{H}:flags=lanczos,"
                f"fps={FPS},setsar=1,format=yuv420p,setpts=PTS-STARTPTS[v{index}]"
            )
            filters.append(
                f"[{index}:a:0]aresample=48000:async=1:first_pts=0,"
                f"asetpts=PTS-STARTPTS[a{index}]"
            )

        joined = "".join(f"[v{i}][a{i}]" for i in range(len(ORDER)))
        filters.append(joined + f"concat=n={len(ORDER)}:v=1:a=1[v][a]")

        subprocess.run(
            [
                "ffmpeg", "-y", "-v", "error", *inputs,
                "-filter_complex", ";".join(filters),
                "-map", "[v]", "-map", "[a]",
                "-c:v", "libx264", "-preset", "fast", "-crf", "18",
                "-pix_fmt", "yuv420p",
                "-c:a", "aac", "-b:a", "192k", "-ar", "48000",
                "-movflags", "+faststart",
                str(LOCAL_MASTER),
            ],
            check=True,
        )

    if stream_copy_safe:
        print("\n⚡ Matching H.264/AAC scene streams — joining without video re-encode")
        subprocess.run(
            [
                "ffmpeg", "-y", "-v", "error",
                "-f", "concat", "-safe", "0", "-i", str(CONCAT_FILE),
                "-map", "0:v:0", "-map", "0:a:0",
                "-c", "copy", "-movflags", "+faststart",
                str(LOCAL_MASTER),
            ],
            check=True,
        )
        copy_valid, copy_media = _vx21_master_valid(LOCAL_MASTER, expected_duration)
        if copy_valid:
            ASSEMBLY_MODE = "STREAM COPY"
        else:
            print(
                "⚠️ Stream-copy timing QA did not remain exact; "
                "using the single normalized fallback encode"
            )
            LOCAL_MASTER.unlink(missing_ok=True)
            _vx21_run_normalized_encode()
            ASSEMBLY_MODE = "ONE NORMALIZED FINAL ENCODE AFTER COPY QA"
    else:
        print("\n🔧 Scene stream settings differ — performing one normalized final encode")
        _vx21_run_normalized_encode()
        ASSEMBLY_MODE = "ONE NORMALIZED FINAL ENCODE"

    local_valid, local_media = _vx21_master_valid(LOCAL_MASTER, expected_duration)
    if not local_valid:
        raise RuntimeError(f"Local final master failed publish QA: {local_media}")

    _vx21_atomic_publish(LOCAL_MASTER, FINAL_MP4)
    master_valid, master_media = _vx21_master_valid(FINAL_MP4, expected_duration)
    if not master_valid:
        raise RuntimeError(f"Published Drive master failed read-back QA: {master_media}")

    print("✅ Final master assembled in /content, QA passed, then published atomically")


# Save/update the master cache immediately after a valid master is confirmed.
cache_entries[cache_key] = {
    "fingerprint": ASSEMBLY_FINGERPRINT,
    "assembler": ASSEMBLER_VERSION,
    "final_file": str(FINAL_MP4),
    "quality": QUALITY_LOCAL,
    "width": W,
    "height": H,
    "fps": FPS,
    "expected_duration": expected_duration,
    "final_duration": float(master_media["duration"]),
    "scene_order": [key for key, _, _ in ORDER],
}
MASTER_CACHE = {"version": 1, "masters": cache_entries}
_vx21_atomic_json(CACHE_FILE, MASTER_CACHE)


# ------------------------------------------------------------
# COMBINED MP3 — REUSE WHEN IT ALREADY MATCHES THE MASTER
# ------------------------------------------------------------

mp3_valid, mp3_media = _vx21_mp3_valid(COMBINED_MP3, float(master_media["duration"]))
mp3_is_new_enough = (
    COMBINED_MP3.exists()
    and COMBINED_MP3.stat().st_mtime_ns >= FINAL_MP4.stat().st_mtime_ns
)
REUSE_MP3 = RESUME and not FORCE and mp3_valid and mp3_is_new_enough

if REUSE_MP3:
    print("♻️ Combined MP3 already valid — SKIP AUDIO EXTRACTION")
else:
    LOCAL_MP3.unlink(missing_ok=True)
    subprocess.run(
        [
            "ffmpeg", "-y", "-v", "error",
            "-i", str(FINAL_MP4), "-vn",
            "-c:a", "libmp3lame", "-b:a", "192k",
            str(LOCAL_MP3),
        ],
        check=True,
    )
    local_mp3_valid, local_mp3_media = _vx21_mp3_valid(
        LOCAL_MP3, float(master_media["duration"])
    )
    if not local_mp3_valid:
        raise RuntimeError(f"Local combined MP3 failed QA: {local_mp3_media}")
    _vx21_atomic_publish(LOCAL_MP3, COMBINED_MP3)
    mp3_valid, mp3_media = _vx21_mp3_valid(
        COMBINED_MP3, float(master_media["duration"])
    )
    if not mp3_valid:
        raise RuntimeError(f"Published combined MP3 failed read-back QA: {mp3_media}")
    print("✅ Combined MP3 extracted locally and published atomically")


# ------------------------------------------------------------
# FINAL OUTPUT CONTRACT READ-BACK + QA REPORT
# ------------------------------------------------------------

_output_contract_violations = _vx21_output_contract_violations()
if _output_contract_violations:
    raise RuntimeError(
        "PHASE 0 OUTPUT CONTRACT FAILED AFTER PUBLISH:\n- "
        + "\n- ".join(_output_contract_violations)
    )

final_duration = float(master_media["duration"])
duration_delta = abs(final_duration - expected_duration)
minutes = int(final_duration // 60)
seconds = final_duration - minutes * 60


OUTRO_SELECTED = any(key == "05_outro" for key, _, _ in ORDER)
OUTRO_TAIL_PREVIEW = SLIDE_OUT / "final_outro_tail_qa.png"
if OUTRO_SELECTED:
    subprocess.run(
        [
            "ffmpeg", "-y", "-v", "error",
            "-ss", f"{max(0.0, final_duration-0.75):.6f}",
            "-i", str(FINAL_MP4),
            "-frames:v", "1", str(OUTRO_TAIL_PREVIEW),
        ],
        check=True,
    )
    if not OUTRO_TAIL_PREVIEW.exists() or OUTRO_TAIL_PREVIEW.stat().st_size < 5_000:
        raise RuntimeError("Final master outro tail-frame QA failed.")
else:
    OUTRO_TAIL_PREVIEW.unlink(missing_ok=True)

qa = {
    "passed": True,
    "assembler_version": ASSEMBLER_VERSION,
    "assembly_fingerprint": ASSEMBLY_FINGERPRINT,
    "scene_order": [label for _, label, _ in ORDER],
    "scene_keys": [key for key, _, _ in ORDER],
    "scene_count": len(ORDER),
    "design_canvas": [3840, 2160],
    "video_output": [int(master_media["width"]), int(master_media["height"])],
    "aspect_ratio": "16:9",
    "fps": float(master_media["fps"]),
    "video_codec": master_media["video_codec"],
    "audio_codec": master_media["audio_codec"],
    "assembly_mode": ASSEMBLY_MODE,
    "master_reused": REUSE_MASTER,
    "combined_mp3_reused": REUSE_MP3,
    "expected_duration": expected_duration,
    "final_duration": final_duration,
    "duration_delta": duration_delta,
    "sections": reports,
    "final_file": str(FINAL_MP4),
    "combined_mp3": str(COMBINED_MP3),
    "combined_mp3_duration": float(mp3_media["duration"]),
    "outro_is_last": bool(OUTRO_SELECTED and ORDER[-1][0] == "05_outro"),
    "outro_tail_preview": str(OUTRO_TAIL_PREVIEW) if OUTRO_SELECTED else None,
    "output_contract": {
        "passed": True,
        "output_root": str(OUTPUT),
        "allowed_directories": list(_ALLOWED_OUTPUT_DIRS.keys()),
        "required_phase0_data": ["phase0_audit.json"],
        "violations": [],
        "temporary_assembly_root": str(ASSEMBLY_WORK),
    },
}
_vx21_atomic_json(QA_FILE, qa)

# Cell 21 local files are disposable. Completed Drive outputs remain untouched.
for _temporary in (LOCAL_MASTER, LOCAL_MP3, CONCAT_FILE):
    _temporary.unlink(missing_ok=True)

print("\n" + "=" * 74)
print("🏆 FPL VORTEX — FINAL VIDEO PASSED")
print("=" * 74)
print("\nFINAL ORDER")
for index, (_, label, _) in enumerate(ORDER, 1):
    print(f"{index}. {label}")

print("\nMASTER")
print("✅ Design canvas : 3840x2160")
print(f"✅ Video output  : {W}x{H}")
print("✅ Aspect ratio  : 16:9 FULL SCREEN")
print(f"✅ Frame rate    : {FPS} fps")
print("✅ Video codec   : H.264")
print("✅ Audio codec   : AAC")
print(f"✅ Duration      : {minutes}:{seconds:05.2f}")
print(f"✅ Assembly      : {ASSEMBLY_MODE}")
print(f"✅ Mode          : {QUALITY_LOCAL}")
print(f"✅ Master reused : {REUSE_MASTER}")
print(f"✅ MP3 reused    : {REUSE_MP3}")
print(f"✅ QA            : {QA_FILE}")
print("✅ Cell 21 consumed completed scene MP4s only — no duplicate rendering")
print("✅ Temporary concat/encode work stayed in /content")

print("\n🎬 FINAL PUBLISHABLE VIDEO")
print(FINAL_MP4)
print("🎧 FINAL COMBINED MP3")
print(COMBINED_MP3)

if OUTRO_SELECTED:
    print("\n👇 FINAL OUTRO TAIL QA — this is the visible ending inside the master MP4")
    display(IPImage(filename=str(OUTRO_TAIL_PREVIEW), width=1200))

